import { inject, Injectable } from '@angular/core';
import { Tag, Verse } from '../verse/verse';
import { CapacitorService } from '../capacitor/capacitor.service';
import { WidgetSync, WidgetTag, WidgetVerse } from './widget-sync.plugin';

@Injectable({
  providedIn: 'root',
})
export class WidgetSyncService {
  private capacitorService = inject(CapacitorService);

  /**
   * Sync favorite verses to the widget's shared storage.
   * Only runs on iOS.
   */
  async syncFavorites(verses: Verse[]): Promise<void> {
    if (!this.capacitorService.ios) {
      return;
    }

    // Widget is always enabled, so always sync
    const widgetVerses: WidgetVerse[] = verses.map((verse) =>
      this.mapVerseToWidgetVerse(verse)
    );

    await WidgetSync.syncFavorites({ verses: widgetVerses });
    await WidgetSync.reloadWidgets();
  }

  /**
   * Set the selected tag for filtering widget verses.
   * Pass null to show all favorites.
   */
  async setSelectedTag(tagId: number | null): Promise<void> {
    if (!this.capacitorService.ios) {
      return;
    }

    await WidgetSync.setSelectedTag({ tagId });
    await WidgetSync.reloadWidgets();
  }

  /**
   * Set the refresh interval (in hours) for verse cycling.
   */
  async setRefreshInterval(intervalHours: number): Promise<void> {
    if (!this.capacitorService.ios) {
      return;
    }

    await WidgetSync.setRefreshInterval({ intervalHours });
    await WidgetSync.reloadWidgets();
  }

  /**
   * Get current widget settings.
   */
  async getWidgetSettings(): Promise<{
    selectedTagId: number | null;
    refreshIntervalHours: number;
  }> {
    if (!this.capacitorService.ios) {
      return { selectedTagId: null, refreshIntervalHours: 12 };
    }

    return WidgetSync.getWidgetSettings();
  }

  /**
   * Reload widget timelines to reflect new data.
   */
  async reloadWidgets(): Promise<void> {
    if (!this.capacitorService.ios) {
      return;
    }

    await WidgetSync.reloadWidgets();
  }

  /**
   * Get the synced verses from widget storage (filtered by selected tag if set).
   */
  async getSyncedVerses(): Promise<WidgetVerse[]> {
    const result = await WidgetSync.getSyncedVerses();
    return result.verses;
  }

  private mapVerseToWidgetVerse(verse: Verse): WidgetVerse {
    return {
      id: verse.id!,
      content: verse.content || '',
      book: verse.book || '',
      chapter: verse.chapter || 0,
      start_verse: verse.start_verse || 0,
      end_verse: verse.end_verse || null,
      tags: (verse.tags || []).map((tag) => this.mapTagToWidgetTag(tag)),
    };
  }

  private mapTagToWidgetTag(tag: Tag): WidgetTag {
    return {
      id: tag.id,
      name: tag.name,
      color: tag.color || null,
    };
  }
}

