import { registerPlugin } from '@capacitor/core';

export interface WidgetVerse {
  id: number;
  content: string;
  book: string;
  chapter: number;
  start_verse: number;
  end_verse: number | null;
  tags: WidgetTag[];
}

export interface WidgetTag {
  id: number;
  name: string;
  color: string | null;
}

export interface WidgetSyncPlugin {
  /**
   * Sync favorite verses to the widget's shared storage
   */
  syncFavorites(options: { verses: WidgetVerse[] }): Promise<void>;

  /**
   * Set the selected tag ID for filtering widget verses
   * Pass null to show all favorites
   */
  setSelectedTag(options: { tagId: number | null }): Promise<void>;

  /**
   * Set the refresh interval (in hours) for verse cycling
   */
  setRefreshInterval(options: { intervalHours: number }): Promise<void>;

  /**
   * Get the current widget settings
   */
  getWidgetSettings(): Promise<{
    selectedTagId: number | null;
    refreshIntervalHours: number;
  }>;

  /**
   * Get the synced verses from widget storage (filtered by selected tag if set)
   */
  getSyncedVerses(): Promise<{ verses: WidgetVerse[] }>;

  /**
   * Reload widget timelines to reflect new data
   */
  reloadWidgets(): Promise<void>;
}

export const WidgetSync = registerPlugin<WidgetSyncPlugin>('WidgetSync', {
  web: () => import('./widget-sync.web').then((m) => new m.WidgetSyncWeb()),
});

